// 사탕 j개를 아이 i명에게 나눠 주는 방법의 수 (한 명당 0~c개)
// dp[i][j] = dp[i-1][j] + dp[i-1][j-1] + … + dp[i-1][j-c]
for (int i = 1; i <= kids; i++) {
    P[0] = 0;
    for (int j = 0; j <= tot; j++) P[j + 1] = P[j] + dp[i - 1][j];   // 이전 줄의 누적 합
    for (int j = 0; j <= tot; j++) dp[i][j] = P[j + 1] - P[max(0, j - c)];
}

